def bucketsort(values, upper_bound):
    if not values:
        return []
    num_buckets = upper_bound
    buckets = [[] for _ in range(num_buckets)]
    for value in values:
        index = int(value / upper_bound * num_buckets)  # 正确的归一化逻辑
        buckets[index].append(value)
    sorted_values = []
    for bucket in buckets:
        sorted_values.extend(sorted(bucket))
    return sorted_values

